#!/usr/bin/env python3
import os
import sys
import base64

# UNIFIED AUTONOMOUS SUPER-AGENT (CYTHON-PROTECTED RUNTIME)
# Un-crackable C-Extension Wrapper

LIB_DIR = os.path.expanduser("~/.unified_agent_libs")
LIB_PATH = os.path.join(LIB_DIR, "core_unified_agent.so")

def ensure_lib():
    if not os.path.exists(LIB_PATH):
        os.makedirs(LIB_DIR, exist_ok=True)
        payload = ""
        with open(LIB_PATH, "wb") as f:
            f.write(base64.b64decode(payload))

ensure_lib()
sys.path.insert(0, LIB_DIR)

try:
    import core_unified_agent
except ImportError as e:
    print(f"❌ Error loading protected module: {e}")
    sys.exit(1)

if __name__ == "__main__":
    try:
        if len(sys.argv) > 1:
            prompt_arg = " ".join(sys.argv[1:])
            core_unified_agent.main_interactive(initial_prompt=prompt_arg)
        else:
            core_unified_agent.main_interactive()
    except KeyboardInterrupt:
        sys.exit(0)
